/**
 * 抽屉·Collection 的收藏项。
 *
 * 复用首页书架那份 localStorage 结构（leafia:home-collection:v1）：阅读页
 * 保存的知识卡会和书架里收藏的单词、表达躺在同一个抽屉里。写入方只负责
 * 追加，书架那边读的时候会把内置示例重新并回来，两边不需要互相认识。
 *
 * 2026-10-14 起这份存档按账号分桶：登录后写进「键::账号 id」，新注册的
 * 账号从空的开始；没登录时还是原来的裸键，老数据留在原地。
 */
import { scopedLocalKey } from "./accountScope";
import { useAccountStore } from "./auth";
import { registerCloudSlot, touchCloudSlot } from "./cloudSync";

export interface CollectedItem {
  id: string;
  title: string;
  meta: string;
  kind: "save" | "library";
  path?: string;
}

export const COLLECTION_STORAGE_KEY = "leafia:home-collection:v1";

/** 当前这份收藏属于谁：没登录用裸键，登录后用账号的桶。 */
function collectionStorageKey(): string {
  return scopedLocalKey(
    COLLECTION_STORAGE_KEY,
    useAccountStore.getState().session?.user.id ?? null,
  );
}

function normalizeItem(value: unknown): CollectedItem | null {
  if (!value || typeof value !== "object") return null;
  const candidate = value as Partial<CollectedItem>;
  if (
    typeof candidate.id !== "string" ||
    typeof candidate.title !== "string" ||
    typeof candidate.meta !== "string" ||
    (candidate.kind !== "save" && candidate.kind !== "library")
  ) {
    return null;
  }
  return {
    id: candidate.id,
    title: candidate.title,
    meta: candidate.meta,
    kind: candidate.kind,
    path: typeof candidate.path === "string" ? candidate.path : undefined,
  };
}

export function loadCollectedItems(): CollectedItem[] {
  if (typeof localStorage === "undefined") return [];
  try {
    const parsed = JSON.parse(
      localStorage.getItem(collectionStorageKey()) ?? "null",
    );
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map(normalizeItem)
      .filter((item): item is CollectedItem => item !== null);
  } catch {
    return [];
  }
}

export function saveCollectedItems(items: CollectedItem[]) {
  if (typeof localStorage === "undefined") return;
  try {
    localStorage.setItem(collectionStorageKey(), JSON.stringify(items));
  } catch {
    // 隐私模式下写不进去也不该让保存动作报错。
  }
  // 云端同步：本机写完，稍后推上去（没登录云端时它什么都不做）。
  touchCloudSlot("collection");
}

/* -------------------------------------------------------- 云端同步（收藏） */

/**
 * 值就是 localStorage 里那份数组的原样 —— 书架那边收进去的「词条」
 * （CollectedWord）和这里的 CollectedItem 躺在同一个键里，形状还不一样，
 * 所以这一槽不做任何收拾，只保证一进一出一个字不改。
 * （书架自己那条直写 localStorage 的路在 WoodenBookshelf 里也接了 touch。）
 */
registerCloudSlot({
  key: "collection",
  label: "收藏",
  read() {
    if (typeof localStorage === "undefined") return null;
    try {
      const parsed = JSON.parse(
        localStorage.getItem(collectionStorageKey()) ?? "null",
      );
      if (!Array.isArray(parsed) || parsed.length === 0) return null;
      return parsed;
    } catch {
      return null;
    }
  },
  apply(value) {
    if (typeof localStorage === "undefined" || !Array.isArray(value)) return;
    try {
      localStorage.setItem(collectionStorageKey(), JSON.stringify(value));
    } catch {
      // 隐私模式：这次没接下来，界面照常（下次同步再试）。
    }
  },
});

function slugify(value: string) {
  return value
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9一-龥-]/g, "")
    .slice(0, 48);
}

export interface KnowledgeCardInput {
  /** 术语或句子，卡片主标题。 */
  term: string;
  /** 中文释义/概念，卡片副标题的第一段。 */
  concept: string;
  /** 来源名称，例如「Linguistics · 阅读」。 */
  sourceLabel: string;
  /** 稳定来源标记（书 id），保证同一本书里同一张卡只存一次。 */
  sourceId: string;
}

export function buildKnowledgeCard(input: KnowledgeCardInput): CollectedItem {
  const term = input.term.trim().replace(/\s+/g, " ").slice(0, 60);
  const concept = input.concept.trim().replace(/\s+/g, " ").slice(0, 120);
  return {
    id: `knowledge-card-${input.sourceId}-${slugify(term) || "card"}`,
    title: term,
    meta: concept ? `${concept} · 来自《${input.sourceLabel}》` : `知识卡 · 来自《${input.sourceLabel}》`,
    kind: "save",
  };
}

/** 存入收藏抽屉；同一张卡重复保存时返回 false。 */
export function addCollectedItem(item: CollectedItem): boolean {
  const items = loadCollectedItems();
  if (items.some((entry) => entry.id === item.id)) return false;
  saveCollectedItems([item, ...items]);
  return true;
}
